/// <reference types="vite/client" />
// The barrel (src/lib/index.ts, generated by scripts/gen-index.mjs) re-exports every component and module of every
// implemented item. `export *` silently drops a name that two modules export, so this test fails on any duplicate.
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import * as barrel from '../src/lib/index';

const sources = import.meta.glob(['../src/lib/*/*.svelte', '../src/lib/*/*.ts']);
const load = (path: string) => sources[`../src/lib/${path}`]!() as Promise<Record<string, unknown>>;

const text = readFileSync(join(__dirname, '..', 'src', 'lib', 'index.ts'), 'utf8');
const components = [...text.matchAll(/export \{ default as (\w+) \} from '\.\/([^']+)\.svelte';/g)].map((m) => [m[1]!, m[2]!] as const);
const modules = [...text.matchAll(/export \* from '\.\/([^']+)\.js';/g)].map((m) => m[1]!);

describe('package barrel', () => {
  it('exports every component and every module name once, with no default export', async () => {
    // A module may re-export a sibling's binding: same value, no clash.
    const owners = new Map<string, string[]>();
    const values = new Map<string, Set<unknown>>();
    const own = (name: string, by: string, value: unknown) => {
      owners.set(name, [...(owners.get(name) ?? []), by]);
      values.set(name, (values.get(name) ?? new Set()).add(value));
    };
    for (const [name, file] of components) own(name, file, (await load(`${file}.svelte`)).default);
    for (const m of modules) {
      const mod = await load(`${m}.ts`);
      expect(Object.keys(mod), m).not.toContain('default');
      for (const [name, value] of Object.entries(mod)) own(name, m, value);
    }
    const duplicates = [...owners].filter(([n, by]) => values.get(n)!.size > 1 || (by.length > 1 && components.some(([c]) => c === n))).map(([n, by]) => `${n}: ${by.join(', ')}`);
    expect(duplicates).toEqual([]);
    expect(Object.keys(barrel).sort()).toEqual([...owners.keys()].sort());
  });

  it('exports the components', () => {
    expect(typeof barrel.Kbd).toBe('function');
  });
});
